from __future__ import annotations

import os
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class MetricComparisonResult:
    resource_a: str
    resource_b: str
    start_time: datetime
    end_time: datetime
    metric_name: str
    namespace: str
    statistic: str
    period: int
    value_a: Optional[float]
    value_b: Optional[float]
    difference: Optional[float]
    percent_change: Optional[float]
    samples_a: int
    samples_b: int


def _to_utc(dt: datetime) -> datetime:
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def _aggregate_datapoints(datapoints: List[Dict[str, Any]], statistic: str) -> tuple[Optional[float], int]:
    if not datapoints:
        return None, 0

    stat_key = statistic.lower()
    values: List[float] = []

    for dp in datapoints:
        if stat_key == "average" and "Average" in dp:
            values.append(float(dp["Average"]))
        elif stat_key == "sum" and "Sum" in dp:
            values.append(float(dp["Sum"]))
        elif stat_key == "minimum" and "Minimum" in dp:
            values.append(float(dp["Minimum"]))
        elif stat_key == "maximum" and "Maximum" in dp:
            values.append(float(dp["Maximum"]))
        elif stat_key == "samplecount" and "SampleCount" in dp:
            values.append(float(dp["SampleCount"]))

    if not values:
        return None, len(datapoints)

    if stat_key in {"average"}:
        return sum(values) / len(values), len(datapoints)
    if stat_key in {"sum", "minimum", "maximum", "samplecount"}:
        # For these stats, combine across points in a consistent way.
        if stat_key == "sum":
            return sum(values), len(datapoints)
        if stat_key == "minimum":
            return min(values), len(datapoints)
        if stat_key == "maximum":
            return max(values), len(datapoints)
        return sum(values), len(datapoints)

    return sum(values) / len(values), len(datapoints)


def _query_metric_data(
    cloudwatch_client: Any,
    namespace: str,
    metric_name: str,
    dimension_name: str,
    dimension_value: str,
    start_time: datetime,
    end_time: datetime,
    period: int,
    statistic: str,
) -> tuple[Optional[float], int]:
    paginator = cloudwatch_client.get_paginator("get_metric_data")

    queries = [
        {
            "Id": "m1",
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": [{"Name": dimension_name, "Value": dimension_value}],
                },
                "Period": period,
                "Stat": statistic,
            },
            "ReturnData": True,
        }
    ]

    datapoints: List[Dict[str, Any]] = []
    for page in paginator.paginate(
        MetricDataQueries=queries,
        StartTime=start_time,
        EndTime=end_time,
        ScanBy="TimestampAscending",
    ):
        for ts in page.get("MetricDataResults", []):
            timestamps = ts.get("Timestamps", [])
            values = ts.get("Values", [])
            for i, value in enumerate(values):
                datapoints.append(
                    {
                        statistic.capitalize(): value,
                        "Timestamp": timestamps[i] if i < len(timestamps) else None,
                    }
                )

    return _aggregate_datapoints(datapoints, statistic)


def compare_cloudwatch_metrics(
    resource_a: str,
    resource_b: str,
    metric_name: str,
    namespace: str,
    dimension_name: str = "InstanceId",
    statistic: str = "Average",
    period: int = 300,
    window_minutes: int = 60,
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    region_name: Optional[str] = None,
) -> MetricComparisonResult:
    """
    Compare the same CloudWatch metric over the same window for two different resources
    or dimension filter values.

    Parameters:
        resource_a: Dimension value for first resource/filter.
        resource_b: Dimension value for second resource/filter.
        metric_name: CloudWatch metric name.
        namespace: CloudWatch namespace, e.g. "AWS/EC2".
        dimension_name: Dimension key used to filter the metric.
        statistic: CloudWatch statistic, e.g. "Average", "Sum", "Minimum", "Maximum".
        period: Granularity in seconds.
        window_minutes: Lookback window if start_time/end_time are not provided.
        start_time: Optional inclusive start time in UTC or local time.
        end_time: Optional exclusive end time in UTC or local time.
        region_name: AWS region, default from environment or boto3.
    """
    if end_time is None:
        end_time = datetime.now(timezone.utc)
    else:
        end_time = _to_utc(end_time)

    if start_time is None:
        start_time = end_time - timedelta(minutes=window_minutes)
    else:
        start_time = _to_utc(start_time)

    if start_time >= end_time:
        raise ValueError("start_time must be earlier than end_time")

    cloudwatch_client = boto3.client("cloudwatch", region_name=region_name or os.getenv("AWS_REGION"))

    try:
        value_a, samples_a = _query_metric_data(
            cloudwatch_client=cloudwatch_client,
            namespace=namespace,
            metric_name=metric_name,
            dimension_name=dimension_name,
            dimension_value=resource_a,
            start_time=start_time,
            end_time=end_time,
            period=period,
            statistic=statistic,
        )
        value_b, samples_b = _query_metric_data(
            cloudwatch_client=cloudwatch_client,
            namespace=namespace,
            metric_name=metric_name,
            dimension_name=dimension_name,
            dimension_value=resource_b,
            start_time=start_time,
            end_time=end_time,
            period=period,
            statistic=statistic,
        )
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"CloudWatch metric query failed: {exc}") from exc

    difference = None if value_a is None or value_b is None else value_a - value_b
    percent_change = None
    if value_a is not None and value_b not in (None, 0):
        percent_change = ((value_a - value_b) / value_b) * 100.0

    return MetricComparisonResult(
        resource_a=resource_a,
        resource_b=resource_b,
        start_time=start_time,
        end_time=end_time,
        metric_name=metric_name,
        namespace=namespace,
        statistic=statistic,
        period=period,
        value_a=value_a,
        value_b=value_b,
        difference=difference,
        percent_change=percent_change,
        samples_a=samples_a,
        samples_b=samples_b,
    )
